def evaluate_expression(expr: str) -> int:
    def evaluate_term(operands: list[int]) -> int:
        return operands[0] + (-1 if len(operands) == 1 else operands[1]) * operands[2]

    def evaluate_binary_operator(operands: list[int]) -> int:
        return evaluate_term(operands[:2]) + evaluate_term(operands[2:])

    def evaluate_unary_operator(operand: int) -> int:
        return -1 * operand

    def evaluate_expression_with_parentheses(expr: str) -> int:
        operators = {'+': evaluate_binary_operator, '-': evaluate_binary_operator, '*': evaluate_term, '(': None, ')': None}
        stack = []
        for char in expr:
            if char in operators:
                if operators[char] is None:
                    stack.append(char)
                else:
                    operand = operators[char](stack.pop(), operators[char](*stack.pop(2:)))
                    stack.append(operand)
            else:
                stack.append(char)

        if len(stack) == 0:
            raise ValueError("Unbalanced parentheses in expression")

        result = operators[stack.pop()](*[operand for operand in stack])
        return result

    return evaluate_expression_with_parentheses(expr)

def evaluate_expression(expr: str) -> int:
    operators = {
        '+': lambda x, y: x + y,
        '-': lambda x, y: x - y,
        '*': lambda x, y: x * y,
    }

    def evaluate_expression_with_parentheses(expr: str) -> int:
        stack = []
        for char in expr:
            if char == '(':
                stack.append(char)
            elif char in operators:
                operands = [stack.pop() for _ in range(2)]
                stack.append(operands[1])
                stack.append(operands[0])
                result = operators[char](*operands)
                stack.append(result)
            else:
                stack.append(int(char))

        if len(stack) > 0:
            raise ValueError("Invalid expression")

        return stack[0]

    return evaluate_expression_with_parentheses(expr.replace("()", ""))

