def search_rotated(nums, target):
    nums.sort()

    # Calculate the pivot index
    pivot_index = int(len(nums) * math.floor(math.random() * (len(nums) - 1)))

    # Check if the pivot is the target
    if nums[pivot_index] == target:
        return pivot_index

    # Check if the pivot is to the left or right of the target
    if target < nums[pivot_index]:
        return search_rotated(nums[:pivot_index], target)
    else:
        return search_rotated(nums[pivot_index + 1:], target)

