def merge_intervals(intervals: list[list[int]]):
    # Convert list of lists to list of tuples
    intervals = [tuple(interval) for interval in intervals]

    # Sort intervals by start
    intervals.sort(key=lambda x: x[0])

    # Merge intervals
    merged_intervals = []
    while len(intervals) > 0:
        current_interval = intervals.pop(0)
        for other_interval in intervals:
            if current_interval[1] >= other_interval[0]:
                merged_intervals.append(current_interval)
                intervals.remove(other_interval)
                break
        else:
            merged_intervals.append(current_interval)

            # Remove overlapping intervals
            intervals.remove(current_interval)

    return sorted(set(chain(*merged_intervals)), key=lambda x: x[0])

