def run_length_encode(s):
    result = []
    count = 1
    for char, cnt in zip(s, iter(s, None)):
        count *= cnt
        result.append((char, count))
    return ''.join(f'{c}{count}' for c, count in result)[1:]

def compress(s: str) -> str:
    return run_length_encode(s)

