def decode_string(s: str) -> str:
    pattern = r'\[([^\[]+)\]'
    matches = re.findall(pattern, s)

    result = []
    for match in matches:
        count_str = match[0]
        text = match[1]

        try:
            count = int(count_str)
        except ValueError:
            result.append(text)
        else:
            result.extend(text * count)

    return ''.join(result)

def decode_string(s: str) -> str:
    def decode_helper(text: str, count: int) -> str:
        if count == 1:
            return text
        if count % 2 != 0:
            raise ValueError("Count must be even")
        return decode_helper(text[1:], count // 2) + decode_helper(text[1:], count // 2)

    return decode_helper(s, int(s[1:]))
